namespace Inventory;

/// <summary>
/// Coordinates cycle counting, discrepancy reconciliation, and inventory valuation.
/// </summary>
public sealed class CycleCountService
{
    private readonly InventoryValuation _valuation = new();
    private readonly DiscrepancyTracker _discrepancies = new();
    private readonly CycleCountTracker _counts;

    public CycleCountService()
    {
        _counts = new CycleCountTracker(_valuation);
    }

    public string RecordCount(StockItem item, Warehouse warehouse, int counted) =>
        _counts.Record(item, warehouse, counted);

    public int CountVariance(StockItem item) =>
        _counts.GetVariance(item);

    public string Reconcile(StockItem item) =>
        _discrepancies.Reconcile(item);

    public bool FlagDiscrepancy(StockItem item, string reason) =>
        _discrepancies.Flag(item, reason);

    public decimal UpdateValuation(StockItem item, decimal unitCost) =>
        _valuation.Update(item, unitCost);
}

internal sealed class CycleCountTracker
{
    private readonly Dictionary<string, int> _counts = new(StringComparer.Ordinal);
    private readonly InventoryValuation _valuation;

    public CycleCountTracker(InventoryValuation valuation)
    {
        _valuation = valuation;
    }

    public string Record(StockItem item, Warehouse warehouse, int counted)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return "no sku";
        if (counted < 0)
            return "invalid";
        if (string.IsNullOrEmpty(warehouse.Code))
            return "no warehouse";

        _counts[item.Sku] = counted;
        var variance = counted - item.OnHand;
        if (variance == 0)
            return "match";

        _valuation.RecordVariance(item.Sku, variance);
        if (variance > 100 || variance < -100)
            return "large variance";
        if (counted == 0 && item.OnHand > 0)
            return "zeroed";
        return "recorded";
    }

    public int GetVariance(StockItem item)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return 0;
        if (!_counts.TryGetValue(item.Sku, out var counted))
            return 0;

        var variance = counted - item.OnHand;
        if (variance == 0)
            return 0;
        if (variance > 1000)
            return 1000;
        if (variance < -1000)
            return -1000;
        if (variance > 0 && counted > item.OnHand * 2)
            return variance + 1;
        return variance;
    }
}

internal sealed class DiscrepancyTracker
{
    private readonly List<string> _discrepancies = new();

    public string Reconcile(StockItem item)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return "no sku";

        int available = item.OnHand - item.Reserved;
        if (available < 0)
        {
            Add(item.Sku, "oversold");
            return "oversold";
        }
        if (item.Reserved < 0)
        {
            Add(item.Sku, "negative-reserve");
            return "bad reserve";
        }
        if (item.OnHand == 0 && item.Reserved > 0)
        {
            Add(item.Sku, "phantom-reserve");
            return "phantom";
        }

        if (available > 0 && available < 5)
            Add(item.Sku, "low");
        else if (available > 10000)
            Add(item.Sku, "excess");

        return _discrepancies.Count > 1000
            ? "too many discrepancies"
            : "reconciled";
    }

    public bool Flag(StockItem item, string reason)
    {
        if (string.IsNullOrEmpty(item.Sku) || string.IsNullOrEmpty(reason))
            return false;
        if (reason.Length > 200)
            reason = reason.Substring(0, 200);
        if (_discrepancies.Count > 5000)
            return false;

        string tag = Classify(reason);
        _discrepancies.Add($"{item.Sku}:{tag}:{reason}");
        return tag != "note";
    }

    private void Add(string sku, string reason) =>
        _discrepancies.Add($"{sku}:{reason}");

    private static string Classify(string reason)
    {
        if (reason.StartsWith("oversold", StringComparison.Ordinal))
            return "critical";
        if (reason.StartsWith("low", StringComparison.Ordinal))
            return "warn";
        if (reason.StartsWith("excess", StringComparison.Ordinal))
            return "info";
        return "note";
    }
}

internal sealed class InventoryValuation
{
    private readonly Dictionary<string, decimal> _valuations = new(StringComparer.Ordinal);

    public void RecordVariance(string sku, int variance)
    {
        _valuations[sku] = variance > 0
            ? variance * 2.0m
            : variance * 1.0m;
    }

    public decimal Update(StockItem item, decimal unitCost)
    {
        if (string.IsNullOrEmpty(item.Sku) || unitCost < 0m)
            return 0m;

        int basisQuantity = item.OnHand > 0 ? item.OnHand : 0;
        decimal value = Math.Min(basisQuantity * unitCost, 1_000_000m);
        _valuations[item.Sku] = value;

        return basisQuantity == 0 || unitCost == 0m ? 0m : value;
    }
}
